:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --snake: #4ecca3;
  --food: #e94560;
  --grid: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  color: var(--accent);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--primary);
  padding: 6px 14px;
  border-radius: 8px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  background: #0a0a1a;
  border-radius: 12px;
  display: block;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  transition: opacity 0.2s;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay-content h2 {
  color: var(--accent);
  font-size: 1.5rem;
}

.overlay-content p {
  line-height: 1.5;
  max-width: 300px;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btn {
  flex: 1;
  min-width: 120px;
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  color: var(--text);
  background: var(--primary);
  border: 2px solid transparent;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
}

.btn:hover:not(:disabled) {
  background: #1a4a7a;
  border-color: var(--accent);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: scale(0.97);
  background: #0a2a4a;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.instructions {
  font-size: 0.875rem;
  text-align: center;
  color: #9aa5b1;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .btn {
    min-width: 100px;
    padding: 10px 14px;
  }
}

(function() {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayMessage = document.getElementById('overlayMessage');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const GRID_SIZE = 20;
  const CELL_SIZE = canvas.width / GRID_SIZE;
  const TICK_MS = 140;

  let snake, direction, nextDirection, food, score, gameState, loopId;

  function resetGame() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 0, y: 0 };
    nextDirection = { x: 0, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    gameState = 'paused';
    clearInterval(loopId);
    loopId = null;
    draw();
  }

  function placeFood() {
    let newFood;
    do {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
    } while (snake.some(seg => seg.x === newFood.x && seg.y === newFood.y));
    food = newFood;
  }

  function startGame() {
    if (gameState === 'playing') return;
    if (gameState === 'gameover') resetGame();
    gameState = 'playing';
    overlay.classList.add('hidden');
    pauseBtn.disabled = false;
    pauseBtn.textContent = 'Pause';
    restartBtn.disabled = false;
    startBtn.disabled = true;
    if (loopId) clearInterval(loopId);
    loopId = setInterval(tick, TICK_MS);
  }

  function pauseGame() {
    if (gameState !== 'playing') return;
    gameState = 'paused';
    clearInterval(loopId);
    loopId = null;
    pauseBtn.textContent = 'Resume';
    overlayTitle.textContent = 'Paused';
    overlayMessage.textContent = 'Game is paused. Press Resume to continue.';
    overlay.classList.remove('hidden');
    startBtn.disabled = true;
  }

  function resumeGame() {
    if (gameState !== 'paused') return;
    gameState = 'playing';
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    loopId = setInterval(tick, TICK_MS);
  }

  function restartGame() {
    clearInterval(loopId);
    loopId = null;
    resetGame();
    startBtn.disabled = false;
    pauseBtn.disabled = true;
    restartBtn.disabled = true;
    pauseBtn.textContent = 'Pause';
    overlayTitle.textContent = 'How to Play';
    overlayMessage.textContent = 'Use arrow keys to move the snake. Eat the red food to grow and score points. Avoid hitting walls or yourself!';
    overlay.classList.remove('hidden');
  }

  function gameOver() {
    gameState = 'gameover';
    clearInterval(loopId);
    loopId = null;
    pauseBtn.disabled = true;
    startBtn.disabled = true;
    overlayTitle.textContent = 'Game Over';
    overlayMessage.textContent = 'Your score: ' + score + '. Press Restart to play again.';
    overlay.classList.remove('hidden');
  }

  function tick() {
    if (gameState !== 'playing') return;

    direction = { ...nextDirection };
    if (direction.x === 0 && direction.y === 0) return;

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID_SIZE || head.y < 0 || head.y >= GRID_SIZE) {
      gameOver();
      return;
    }

    if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function draw() {
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#1a1a3a';
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(canvas.width, i * CELL_SIZE);
      ctx.stroke();
    }

    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL_SIZE + 2, food.y * CELL_SIZE + 2, CELL_SIZE - 4, CELL_SIZE - 4);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4ecca3' : '#3aa88a';
      ctx.fillRect(seg.x * CELL_SIZE + 1, seg.y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
    });
  }

  document.addEventListener('keydown', (e) => {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(key)) {
      e.preventDefault();
      if (gameState !== 'playing') return;
      if (key === 'ArrowUp' && direction.y !== 1) nextDirection = { x: 0, y: -1 };
      else if (key === 'ArrowDown' && direction.y !== -1) nextDirection = { x: 0, y: 1 };
      else if (key === 'ArrowLeft' && direction.x !== 1) nextDirection = { x: -1, y: 0 };
      else if (key === 'ArrowRight' && direction.x !== -1) nextDirection = { x: 1, y: 0 };
    }
  });

  startBtn.addEventListener('click', startGame);
  pauseBtn.addEventListener('click', () => {
    if (gameState === 'playing') pauseGame();
    else if (gameState === 'paused') resumeGame();
  });
  restartBtn.addEventListener('click', restartGame);

  resetGame();
  overlayTitle.textContent = 'How to Play';
  overlayMessage.textContent = 'Use arrow keys to move the snake. Eat the red food to grow and score points. Avoid hitting walls or yourself!';
  startBtn.disabled = false;
  pauseBtn.disabled = true;
  restartBtn.disabled = true;
  overlay.classList.remove('hidden');
})();
